mapper.select:
SELECT BASE.MBRSH_SQ AS mbrshSq , BASE.USER_ID AS userId , BASE.USER_NM AS userNm , D.MESSAGE_CN AS deptNm , (SELECT B.MESSAGE_CN FROM CM_CODE_DETAIL A INNER JOIN CM_MESSAGE_LANG B ON B.LANG_KEY = A.CODE_LANG_KEY AND B.CMPNY_CD = A.CMPNY_CD WHERE A.CODE_ID = 'CMMNCODE.560' AND A.USE_FL = 'Y' AND A.CMPNY_CD = BASE.CMPNY_CD AND A.DETAIL_CODE_ID = BASE.OFCPS_NM_KEY AND B.LANG_CODE = #{languageCode} ) AS ofcpsNm FROM ( SELECT A.MBRSH_SQ , A.USER_ID , CASE WHEN #{languageCode} = 'en_US' THEN B.USER_ENG_NM ELSE B.USER_NM END AS USER_NM , C.DEPT_NM_KEY , A.CMPNY_CD , A.OFCPS_NM_KEY FROM CM_USER_ORGNZT_MBRSH A INNER JOIN CM_USER B ON A.USER_ID = B.USER_ID LEFT JOIN CM_DEPT C ON A.DEPT_CD = C.DEPT_CD AND A.CMPNY_CD = C.CMPNY_CD WHERE A.CMPNY_CD = #{companyCode} AND A.USE_FL = 'Y' ) BASE LEFT JOIN CM_MESSAGE_LANG D ON D.LANG_KEY = BASE.DEPT_NM_KEY AND D.CMPNY_CD = BASE.CMPNY_CD AND D.LANG_CODE = #{languageCode}
AND CONCAT(BASE.USER_ID, BASE.USER_NM) LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY BASE.USER_NM

SELECT COUNT(1)
  FROM CM_DEPT
 WHERE CMPNY_CD = #{companyCode}
   AND UPPER_DEPT_CD = #{deptCd}
   AND USE_FL = 'Y'

SELECT COUNT(1)
  FROM CM_USER_ORGNZT_MBRSH
 WHERE CMPNY_CD = #{companyCode}
   AND DEPT_CD = #{deptCd}
   AND USE_FL = 'Y'

SELECT BASE.MBRSH_SQ AS mbrshSq , BASE.USER_ID AS userId , BASE.USER_NM AS userNm , D.MESSAGE_CN AS deptNm FROM ( SELECT A.MBRSH_SQ , A.USER_ID , CASE WHEN #{languageCode} = 'en_US' THEN B.USER_ENG_NM ELSE B.USER_NM END AS USER_NM , C.DEPT_NM_KEY , A.CMPNY_CD FROM CM_USER_ORGNZT_MBRSH A INNER JOIN CM_USER B ON B.USER_ID = A.USER_ID LEFT JOIN CM_DEPT C ON A.DEPT_CD = C.DEPT_CD AND A.CMPNY_CD = C.CMPNY_CD WHERE A.CMPNY_CD = #{companyCode} AND A.USE_FL = 'Y' ) BASE LEFT JOIN CM_MESSAGE_LANG D ON D.LANG_KEY = BASE.DEPT_NM_KEY AND D.CMPNY_CD = BASE.CMPNY_CD AND D.LANG_CODE = #{languageCode}
AND CONCAT(BASE.USER_ID, BASE.USER_NM) LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY BASE.USER_NM

SELECT COUNT(1)
  FROM CM_DEPT
 WHERE CMPNY_CD = #{companyCode}
   AND DEPT_CD = #{deptCd}

mapper.insert:
INSERT INTO CM_USER (USER_ID, USER_NM, USER_ENG_NM, USER_TYPE, PASSWORD, GENDER_CD, BRTHDY, PASSWORD_HINT, PASSWORD_CNSR, NATION_CD, ZIP_CD, ADRES_ONE, ADRES_TWO, CITY_NM, STATE_NM, HOUSE_TELNO, MBTLNUM, FXNUM, EMAIL_ADRES, SBSCRB_STTUS, CREATION_ID, CREATION_DT
, FILE_SQ
)
VALUES (#{userId}, #{userNm}, #{userEngNm}, COALESCE(NULLIF(#{userType}, ''), 'USER'), #{password}, #{genderCd}, #{brthdy}, #{passwordHint}, #{passwordCnsr}, #{nationCd}, #{zipCd}, #{adresOne}, #{adresTwo}, #{cityNm}, #{stateNm}, #{houseTelno}, #{mbtlnum}, #{fxnum}, #{emailAdres}, COALESCE(NULLIF(#{sbscrbSttus}, ''), 'P'), #{creationId}, NOW()
, CAST(#{profileFileSq} AS DECIMAL(30,0))
)

mapper.update:
UPDATE CM_USER
   SET USER_NM = #{userNm}
   , USER_ENG_NM = #{userEngNm}
   , GENDER_CD = #{genderCd}
   , BRTHDY = #{brthdy}
   , ZIP_CD = #{zipCd}
   , ADRES_ONE = #{adresOne}
   , ADRES_TWO = #{adresTwo}
   , CITY_NM = #{cityNm}
   , STATE_NM = #{stateNm}
   , NATION_CD = #{nationCd}
   , HOUSE_TELNO = #{houseTelno}
   , MBTLNUM = #{mbtlnum}
   , FXNUM = #{fxnum}
   , PASSWORD_HINT = #{passwordHint}
   , PASSWORD_CNSR = #{passwordCnsr}
   , EMAIL_ADRES = #{emailAdres}

   , FILE_SQ =

           NULL
           CAST(#{profileFileSq} AS DECIMAL(30,0))


   , UPDATE_ID = #{updateId}
   , UPDATE_DT = NOW()
 WHERE USER_ID = #{userId}

UPDATE CM_USER_ORGNZT_MBRSH
DEPT_CD = #{deptCd, jdbcType=VARCHAR}, EMPL_NO = #{emplNo, jdbcType=VARCHAR}, OFFM_TELNO = #{offmTelno, jdbcType=VARCHAR}, EMAIL_ADRES = #{emailAdres, jdbcType=VARCHAR}, OFCPS_NM_KEY = #{ofcpsCd, jdbcType=VARCHAR}, ECNY_YMD = #{ecnyYmd, jdbcType=VARCHAR}, RETIRE_YMD = #{retireYmd, jdbcType=VARCHAR}, UPDATE_ID = #{updateId}, UPDATE_DT = NOW()
WHERE MBRSH_SQ = #{mbrshSq} AND USER_ID = #{userId}

UPDATE CM_DEPT
   SET    DEPT_NM_KEY = #{deptNmKey}
        , UPPER_DEPT_CD = #{upperDeptCd}
        , DEPT_GRAD_CD = #{deptGradCd}
        , DPRLR_ID = #{dprlrId}
        , EXPRTN_YMD = #{exprtnYmd}
        , USE_FL = #{useFl}
        , SORT_ORD = #{sortOrd}
        , UPDATE_ID = #{updateId}
        , UPDATE_DT = NOW()
 WHERE CMPNY_CD = #{companyCode} AND DEPT_CD = #{deptCd}

UPDATE CM_DEPT
   SET USE_FL = 'N'
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = NOW()
 WHERE CMPNY_CD = #{companyCode}
   AND DEPT_CD = #{deptCd}

UPDATE CM_USER 
SET PASSWORD  = #{password}
  , UPDATE_ID = #{updateId}
  , UPDATE_DT = NOW() 
WHERE USER_ID = #{userId}

UPDATE CM_USER_ORGNZT_MBRSH
   SET DEPT_CD = #{deptCd}
   , EMPL_NO = #{emplNo}
   , OFFM_TELNO = #{offmTelno}
   , EMAIL_ADRES = #{emailAdres}
   , OFCPS_NM_KEY = #{ofcpsCd}
   , ECNY_YMD = #{ecnyYmd}
   , RETIRE_YMD = #{retireYmd}
   , UPDATE_ID = #{updateId}
   , UPDATE_DT = NOW()
 WHERE MBRSH_SQ = #{mbrshSq}

UPDATE CM_USER_ORGNZT_MBRSH
   SET DEPT_CD = #{deptCd}
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = NOW()
 WHERE MBRSH_SQ = #{mbrshSq}
   AND CMPNY_CD = #{companyCode}
   AND USER_ID = #{userId}
   AND USE_FL = 'Y'

UPDATE CM_USER_ORGNZT_MBRSH 
SET DEPT_CD = NULL
  , UPDATE_ID = #{updateId}
  , UPDATE_DT = NOW() 
WHERE MBRSH_SQ = #{mbrshSq}

UPDATE CM_USER
   SET SBSCRB_STTUS = #{sbscrSttus}
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = NOW()
 WHERE USER_ID = #{userId}

UPDATE CM_USER
SET PASSWORD = #{new_password}
WHERE USER_ID = #{login_id}
  AND PASSWORD = #{old_password}
